fn counted_map(f:&Fp,rows:&[Vec<u64>],ms:&[[usize;4]],k:[u64;4])->[u64;4]{let mut powers=[[1u64;6];4];for j in 0..4{for n in 1..6{powers[j][n]=f.mul(powers[j][n-1],k[j]);}}let vs:Vec<_>=ms.iter().map(|e|(0..4).fold(1,|s,j|f.mul(s,powers[j][e[j]]))).collect();std::array::from_fn(|i|rows[i].iter().zip(&vs).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b))))}
fn diff(a:&counted::Counts,b:&counted::Counts)->counted::Counts{let mut out=a.clone();for(p,v)in &mut out{for j in 0..16{v[j]-=b.get(p).map_or(0,|x|x[j]);}}out}
